int register_genl_family(struct genl_family *family)
{
    int err = 0;
    struct genl_family *tmp;

    if (!family || !family->name || family->version <= 0) {
        return -EINVAL;
    }

    if (family->maxattr > 0 && !family->ops) {
        return -EINVAL;
    }

    if (family->n_ops > 0 && !family->ops) {
        return -EINVAL;
    }

    if (family->n_mcgrps > 0 && !family->mcgrps) {
        return -EINVAL;
    }

    write_lock(&genl_mutex);

    list_for_each_entry(tmp, &genl_families, entry) {
        if (strcmp(tmp->name, family->name) == 0) {
            write_unlock(&genl_mutex);
            return -EEXIST;
        }
    }

    if (!family->id) {
        for (int i = 1; i < GENL_ID_MAX; i++) {
            if (!genl_id_to_name[i]) {
                family->id = i;
                break;
            }
        }
    }

    if (!family->id) {
        write_unlock(&genl_mutex);
        return -ENOBUFS;
    }

    genl_id_to_name[family->id] = family->name;
    genl_name_to_id[family->id] = family;

    if (family->n_attrs > 0 && !family->attr_policy) {
        family->attr_policy = kcalloc(family->n_attrs + 1, sizeof(nla_policy), GFP_KERNEL);
        if (!family->attr_policy) {
            err = -ENOMEM;
            goto err_out;
        }
    }

    for (int i = 0; i < family->n_ops; i++) {
        if (!family->ops[i].doit && !family->ops[i].dumpit) {
            err = -EINVAL;
            goto err_out;
        }
    }

    for (int i = 0; i < family->n_mcgrps; i++) {
        if (!family->mcgrps[i].name || family->mcgrps[i].id <= 0) {
            err = -EINVAL;
            goto err_out;
        }
    }

    list_add_tail(&family->entry, &genl_families);

    genl_notify_family(family, GENL_REGISTER);

    write_unlock(&genl_mutex);

    return 0;

err_out:
    write_unlock(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family) {
    int err = 0;
    struct genl_family *existing_family;

    if (!family || !family->name || !family->version || !family->ops) {
        return -EINVAL;
    }

    if (genl_validate_ops(family) < 0) {
        return -EINVAL;
    }

    down_write(&genl_mutex);

    existing_family = genl_find_family(family->name);
    if (existing_family) {
        up_write(&genl_mutex);
        return -EEXIST;
    }

    if (family->id >= GENL_ID_MIN && family->id < GENL_ID_MAX) {
        if (genl_fam_by_id[family->id]) {
            up_write(&genl_mutex);
            return -EBUSY;
        }
    } else {
        family->id = genl_alloc_id();
        if (family->id < 0) {
            up_write(&genl_mutex);
            return family->id;
        }
    }

    if (family->n_attrs && !family->attr_policy) {
        family->attr_policy = kzalloc(family->n_attrs * sizeof(struct nla_policy), GFP_KERNEL);
        if (!family->attr_policy) {
            up_write(&genl_mutex);
            return -ENOMEM;
        }
    }

    if (family->mcgrps) {
        if (genl_validate_multicast_groups(family) < 0) {
            kfree(family->attr_policy);
            up_write(&genl_mutex);
            return -EINVAL;
        }
    }

    genl_fam_by_id[family->id] = family;
    list_add_tail(&family->entry, &genl_families);

    up_write(&genl_mutex);

    genl_notify_family_registered(family);

    if (family->mcgrps) {
        genl_notify_multicast_groups_registered(family);
    }

    return 0;
}

int genl_register_family(struct genl_family *family) {
    int err;

    if (!family)
        return -EINVAL;

    if (family->version == 0)
        return -EINVAL;

    if (family->ops && family->n_ops) {
        int i;
        for (i = 0; i < family->n_ops; i++) {
            if (!family->ops[i].cmd || family->ops[i].cmd == 0)
                return -EINVAL;
        }
    }

    mutex_lock(&genl_mutex);

    if (genl_find_family(family->name))
        return -EEXIST;

    if (family->id == 0) {
        family->id = genl_get_unique_id();
        if (family->id < 0) {
            mutex_unlock(&genl_mutex);
            return family->id;
        }
    }

    if (family->max_attr > 0 && !family->attr_policy) {
        family->attr_policy = kzalloc((family->max_attr + 1) * sizeof(struct nla_policy), GFP_KERNEL);
        if (!family->attr_policy) {
            err = -ENOMEM;
            goto err_out;
        }
    }

    err = genl_register_ops(family);
    if (err < 0)
        goto err_out;

    list_add_tail(&family->list, &genl_fam_list);

    mutex_unlock(&genl_mutex);

    genl_notify_family_registered(family);

    return 0;

err_out:
    if (family->attr_policy && family->max_attr > 0)
        kfree(family->attr_policy);
    mutex_unlock(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family)
{
    int err;
    struct genl_family *tmp;
    int i;

    if (!family)
        return -EINVAL;

    if (!family->name || strlen(family->name) == 0)
        return -EINVAL;

    if (!family->version || family->version > GENL_VERSION_MAX)
        return -EINVAL;

    for (i = 0; i < family->n_attrs; i++) {
        if (!family->attr_attrs[i].name || strlen(family->attr_attrs[i].name) == 0)
            return -EINVAL;
    }

    down_write(&genl_mutex);

    for (i = 0; i < GENL_ID_MAX; i++) {
        if (genl_families[i] && !strcmp(genl_families[i]->name, family->name)) {
            up_write(&genl_mutex);
            return -EEXIST;
        }
    }

    for (i = 0; i < GENL_ID_MAX; i++) {
        if (!genl_families[i]) {
            family->id = i;
            genl_families[i] = family;
            break;
        }
    }

    if (i == GENL_ID_MAX) {
        up_write(&genl_mutex);
        return -ENOSPC;
    }

    if (family->mcgrps && family->n_mcgrps) {
        for (i = 0; i < family->n_mcgrps; i++) {
            if (!family->mcgrps[i].name || strlen(family->mcgrps[i].name) == 0) {
                genl_unregister_family(family);
                up_write(&genl_mutex);
                return -EINVAL;
            }
        }
    }

    up_write(&genl_mutex);

    return 0;
}

int genl_register_family(struct genl_family *family)
{
    int err = 0;
    struct genl_family *tmp;
    struct nlmsghdr *nlh;
    struct genl_family_dump_req req;

    if (!family)
        return -EINVAL;

    if (family->version == 0 || family->module == NULL)
        return -EINVAL;

    if (!family->ops || family->n_ops == 0)
        return -EINVAL;

    mutex_lock(&genl_mutex);

    list_for_each_entry(tmp, &genl_families, list) {
        if (strcmp(family->name, tmp->name) == 0) {
            err = -EEXIST;
            goto out_unlock;
        }
    }

    if (!family->id) {
        int id;

        for (id = 1; id < GENL_ID_UP; id++) {
            if (!genl_families_byid[id])
                break;
        }

        if (id >= GENL_ID_UP)
            id = GENL_ID_UP;

        family->id = id;
    }

    if (family->id >= GENL_ID_ALLOC) {
        err = -ENOMEM;
        goto out_unlock;
    }

    if (family->id < GENL_ID_UP) {
        genl_families_byid[family->id] = family;
    }

    list_add_tail(&family->list, &genl_families);

    if (family->n_attrs > 0) {
        family->attrbuf = kmalloc(family->n_attrs * sizeof(void *), GFP_KERNEL);
        if (!family->attrbuf) {
            err = -ENOMEM;
            goto out_remove;
        }
    }

    for (int i = 0; i < family->n_multicast_groups; i++) {
        if (!family->mcgrps[i].name || !family->mcgrps[i].id) {
            err = -EINVAL;
            goto out_cleanup;
        }
    }

    nlh = genlmsg_put(skb, 0, 0, family, 0, GENL_ID_CTRL, NLMSG_DONE, 0);
    if (!nlh) {
        err = -ENOMEM;
        goto out_cleanup;
    }

    err = nla_put_string(skb, CTRL_ATTR_FAMILY_NAME, family->name);
    if (err < 0)
        goto out_cleanup;

    err = nla_put_u16(skb, CTRL_ATTR_FAMILY_ID, family->id);
    if (err < 0)
        goto out_cleanup;

    err = nla_put_u32(skb, CTRL_ATTR_VERSION, family->version);
    if (err < 0)
        goto out_cleanup;

    for (int i = 0; i < family->n_ops; i++) {
        err = nla_put(skb, CTRL_ATTR_OPS, sizeof(*family->ops[i]), family->ops[i]);
        if (err < 0)
            goto out_cleanup;
    }

    for (int i = 0; i < family->n_multicast_groups; i++) {
        err = nla_put(skb, CTRL_ATTR_MCAST_GRP_NAME, strlen(family->mcgrps[i].name), family->mcgrps[i].name);
        if (err < 0)
            goto out_cleanup;
        err = nla_put_u32(skb, CTRL_ATTR_MCAST_GRP_ID, family->mcgrps[i].id);
        if (err < 0)
            goto out_cleanup;
    }

    nlmsg_end(skb, nlh);

    mutex_unlock(&genl_mutex);

    return 0;

out_cleanup:
    if (family->attrbuf)
        kfree(family->attrbuf);
    family->attrbuf = NULL;
out_remove:
    list_del(&family->list);
out_unlock:
    mutex_unlock(&genl_mutex);
    return err;
}
